-- Generated by dag_tools.systemlink.sql from the rule table in
-- dag_tools.systemlink.measurements. Do not edit by hand: a test
-- compares the generator's output against this file byte for byte.

with conformed as (
    select * from {{ var('mfg_trace_conf_result_relation') }}
),

-- The attempt order. Deterministic, including the tie-break: an
-- order that can flip between runs gives a reader a different
-- `attempt_seq` for the same attempt every time the model is built.
attempts as (
    select
        conformed.*,
        row_number() over (
            partition by part_number, serial_number, program_name
            order by started_at asc, result_id asc
        ) as attempt_seq
    from conformed
),

-- The newest attempt that actually REACHED a terminal state, which
-- is what `is_latest` is defined against. The simplification to
-- `attempt_seq = max(attempt_seq)` marks an in-flight run as the
-- latest, so a reader filtering to one row per unit gets a row whose
-- result is not in yet -- which reads as a correct answer.
terminal as (
    select
        attempts.*,
        max(case when is_terminal then attempt_seq end) over (
            partition by part_number, serial_number, program_name
        ) as latest_terminal_seq
    from attempts
)

select
    result_id,
    part_number,
    part_number_raw,
    serial_number,
    serial_number_raw,
    program_name,
    status_type,
    is_terminal,
    started_at,
    updated_at,
    duration_s,
    system_id,
    host_name,
    operator_ref,
    workspace,
    attempt_seq,
    coalesce(is_terminal and (attempt_seq = latest_terminal_seq), false) as is_latest,
    (attempt_seq = 1) as is_first,
    source_system,
    source_record_id,
    extracted_at,
    loaded_at
from terminal
